INSERT IGNORE INTO `terms_templates` (`id`,`name`,`scope`,`content_html`,`current_version`,`is_default`,`is_active`,`created_by`,`updated_by`,`created_at`,`updated_at`,`deleted_at`) VALUES
('9ac836d7-a2a4-500b-98bf-dc2c619c4c65','Standard Terms & Conditions','GLOBAL','<ol><li>All rates are exclusive of GST @18% unless mentioned.</li><li>Quotation valid for 30 days from date of issue.</li><li>Any work beyond approved scope will be treated as an extra item and billed at agreed rates.</li><li>Client to provide water and electricity at site free of cost.</li><li>Disputes subject to Delhi jurisdiction only.</li></ol>',2,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('e2ec5efa-3bee-54fd-93ba-6e8eaf3cfd9f','BOQ Terms - Turnkey Interiors','BOQ','<ol><li>Quantities are indicative and will be measured at site on completion.</li><li>Brands as per approved material schedule; equivalent alternatives only with written approval.</li><li>Loose furniture, soft furnishings and appliances excluded unless listed.</li><li>Miscellaneous provision @10% covers minor consumables and site contingencies.</li></ol>',2,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('7b51c4ef-1984-5a2e-a83e-a900c3d0b67a','Budget Estimate Terms','ESTIMATE','<ol><li>This is a budgetary estimate prepared at concept stage; variance of +/-10% expected.</li><li>Design fee and PMC fee shown separately.</li><li>Final BOQ will be issued after GFC drawings.</li></ol>',1,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('1a4acd77-5dae-590a-853b-3d39b3a7e51d','Plan of Action Terms','PLAN_OF_ACTION','<ol><li>Timelines assume timely approvals (within 5 working days) and payments as per schedule.</li><li>Society/RWA restrictions on working hours may extend durations.</li><li>Monsoon (Jul-Aug) may affect civil and external works.</li></ol>',1,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('06fbe897-b020-5b1a-a191-f3eb19035a2e','Design Consultancy Agreement Terms','PROJECT','<ol><li>Design fee payable in stages: 10% token, 30% on concept approval, 30% on GFC drawings, 30% during execution.</li><li>Two rounds of revisions included per design stage.</li><li>Site visits: weekly during execution.</li></ol>',1,0,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL);
